1211|#endif
1212|#ifdef obj_begin
1213|  obj_begin ();
1214|#endif
1215|
1216|  /* Skip argv[0].  */
1217|  argv++;
1218|  argc--;
1219|
1220|  while (argc--)
1221|    {
