290|static inline int
291|address_bytes (void)
292|{
293|  /* Choose smallest of 1, 2, 4, 8 bytes that is large enough to
294|     contain an address.  */
295|  int n = (stdoutput->arch_info->bits_per_address - 1) / 8;
296|  n |= n >> 1;
297|  n |= n >> 2;
298|  n += 1;
299|  return n;
300|}

