810|void
811|read_a_source_file (const char *name)
812|{
813|  char nul_char;
814|  char next_char;
815|  char *s;		/* String of symbol, '\0' appended.  */
816|  long temp;
817|  const pseudo_typeS *pop;
818|
819|#ifdef WARN_COMMENTS
820|  found_comment = 0;
821|#endif
822|
823|  buffer = input_scrub_new_file (name);
824|
825|  listing_file (name);
826|  listing_newline (NULL);
827|  register_dependency (name);
828|
829|  /* Generate debugging information before we've read anything in to denote
830|     this file as the "main" source file and not a subordinate one
831|     (e.g. N_SO vs N_SOL in stabs).  */
832|  generate_file_debug ();
833|
834|  while ((buffer_limit = input_scrub_next_buffer (&input_line_pointer)) != 0)
835|    {				/* We have another line to parse.  */
836|#ifndef NO_LISTING
837|      /* In order to avoid listing macro expansion lines with labels
838|	 multiple times, keep track of which line was last issued.  */
839|      static char *last_eol;
840|
841|      last_eol = NULL;
842|#endif
843|      while (input_line_pointer < buffer_limit)
844|	{
845|	  bool was_new_line;
846|	  /* We have more of this buffer to parse.  */
847|
848|	  /* We now have input_line_pointer->1st char of next line.
849|	     If input_line_pointer [-1] == '\n' then we just
850|	     scanned another line: so bump line counters.  */
851|	  was_new_line = is_end_of_line[(unsigned char) input_line_pointer[-1]];
852|	  if (was_new_line)
853|	    {
854|	      symbol_set_value_now (&dot_symbol);
855|#ifdef md_start_line_hook
856|	      md_start_line_hook ();
857|#endif
858|	      if (input_line_pointer[-1] == '\n')
859|		bump_line_counters ();
860|	    }
861|
862|#ifndef NO_LISTING
863|	  /* If listing is on, and we are expanding a macro, then give
864|	     the listing code the contents of the expanded line.  */
865|	  if (listing)
866|	    {
867|	      if ((listing & LISTING_MACEXP) && macro_nest > 0)
