57|static void
58|alloc_seginfo (segT seg)
59|{
60|  segment_info_type *seginfo;
61|
62|  seginfo = obstack_alloc (&notes, sizeof (*seginfo));
63|  memset (seginfo, 0, sizeof (*seginfo));
64|  seginfo->bfd_section = seg;
